    func testBobMatchesReferenceEngine() {
        for c in bobCases {
            XCTAssertEqual(Beats.bobPeriods(cycleSeconds: c.cycleSeconds), c.periods, c.id)
            for (cycleTime, expected) in c.samples {
                let b = Beats.loop(cycleTime: cycleTime, cycleSeconds: c.cycleSeconds)
                XCTAssertEqual(b.rootScaleY, expected, accuracy: tolerance,
                               "\(c.id) at cycleTime=\(cycleTime)")
            }
        }
    }

    func testOneShotsMatchReferenceEngine() {
        for c in shotCases {
            for (t, sx, sy, ty, rot, ear, tail) in c.samples {
                let b = c.shot.offsets(at: t)
                XCTAssertEqual(b.rootScaleX, sx, accuracy: tolerance, "\(c.name).scaleX at \(t)")
                XCTAssertEqual(b.rootScaleY, sy, accuracy: tolerance, "\(c.name).scaleY at \(t)")
                XCTAssertEqual(b.rootTranslateY, ty, accuracy: tolerance, "\(c.name).translateY at \(t)")
                XCTAssertEqual(b.rootRotate, rot, accuracy: tolerance, "\(c.name).rotate at \(t)")
                XCTAssertEqual(b.earTranslateY, ear, accuracy: tolerance, "\(c.name).ear at \(t)")
                XCTAssertEqual(b.tailTranslateX, tail, accuracy: tolerance, "\(c.name).tail at \(t)")
            }
        }
    }

    /// A one-shot must come to rest and stay there. A beat that ends a hair off
    /// zero leaves the body permanently displaced, and the next one starts from
    /// there — so the error accumulates over a session rather than showing up
    /// once.
    func testOneShotsReturnToRest() {
        for c in shotCases {
            for t in [c.duration, c.duration + 0.5, c.duration * 3] {
                let b = c.shot.offsets(at: t)
                XCTAssertEqual(b.rootScaleX, 0, accuracy: tolerance, "\(c.name) scaleX at \(t)")
                XCTAssertEqual(b.rootScaleY, 0, accuracy: tolerance, "\(c.name) scaleY at \(t)")
                XCTAssertEqual(b.rootTranslateY, 0, accuracy: tolerance, "\(c.name) translateY at \(t)")
                XCTAssertEqual(b.rootRotate, 0, accuracy: tolerance, "\(c.name) rotate at \(t)")
            }
        }
    }

    /// The bob never stops, and that is the point: during an inhale it is
    /// swamped by the body's own travel, but during a four-second hold it is the
    /// only thing moving. A bob that rested would make a hold read as a stalled
    /// player rather than as a held breath.
    func testBobNeverRests() {
        for c in bobCases {
            let moved = c.samples.contains { abs($0.1) > 1e-6 }
            XCTAssertTrue(moved, "\(c.id): the bob never moves")
        }
    }

    /// A pose swap goes where the body is moving **fastest**, because a cut is
    /// hidden when it is smaller than its surroundings.
    ///
    /// Speed — not displacement, and not a control point. Those are three
    /// different instants and only the first hides a cut. The earlier version of
    /// this test asked only that the swap moved more than the beat's endpoints,
    /// which is true almost everywhere; it passed while both constants sat on
    /// control-point positions rather than velocity peaks.
    func testSwapSitsAtTheFastestInstant() {
        for shot in Beats.oneShots {
            let steps = 2000
            let dt = shot.duration / Double(steps)

            // Both channels normalised by their own range, so neither the scale
            // nor the lift dominates purely because of its units.
            func speed(at t: Double) -> Double {
                let a = shot.offsets(at: max(0, t - dt))
                let b = shot.offsets(at: t)
                return hypot((b.rootScaleY - a.rootScaleY) / dt / 0.05,
                             (b.rootTranslateY - a.rootTranslateY) / dt / 20)
            }

            var peak = 0.0
            var peakAt = 0.0
            for i in 1...steps {
                let t = Double(i) * dt
                let v = speed(at: t)
                if v > peak { peak = v; peakAt = t }
            }

            XCTAssertEqual(shot.swapAt, peakAt, accuracy: 0.01,
                           "\(shot.name): declares \(shot.swapAt), fastest is \(peakAt)")
            XCTAssertGreaterThan(speed(at: shot.swapAt), peak * 0.98,
                                 "\(shot.name): the swap is not at the peak")
        }
    }
}
